import { z } from "zod";
import type { DsIndex } from "./design-system.js";
import type { ApplyPlanResult, MutationPlan } from "./plan.js";
import type { NodeSnapshot, Rgba } from "./snapshot.js";

export const PROTOCOL_VERSION = 1;
export const DEFAULT_BRIDGE_PORT = 3055;
export const HEARTBEAT_INTERVAL_MS = 5_000;

/**
 * Pairing codes are generated by the plugin UI and typed by the human into the agent chat.
 * 8 chars from a 31-symbol alphabet (no 0/O/1/I/L) ≈ 8.5e11 combinations.
 */
export const PAIRING_ALPHABET = "23456789ABCDEFGHJKMNPQRSTUVWXYZ";
export const PairingCodeSchema = z
  .string()
  .transform((s) => s.toUpperCase().replace(/[\s-]/g, ""))
  .pipe(z.string().regex(new RegExp(`^[${PAIRING_ALPHABET}]{8}$`), "pairing code must be 8 characters, e.g. K7QM-2XPA"));

export function formatPairingCode(code: string): string {
  return `${code.slice(0, 4)}-${code.slice(4)}`;
}

// ---------------------------------------------------------------------------
// Wire messages (WebSocket, JSON)
// ---------------------------------------------------------------------------

export const RpcErrorSchema = z.object({ code: z.string(), message: z.string(), data: z.unknown().optional() });
export type RpcError = z.infer<typeof RpcErrorSchema>;

export const ClientMessageSchema = z.discriminatedUnion("type", [
  /** Figma plugin UI announces itself and the pairing code it displays. */
  z.object({
    type: z.literal("register_plugin"),
    protocolVersion: z.number().int(),
    pairingCode: PairingCodeSchema,
    fileName: z.string().optional(),
  }),
  /** An agent (MCP server) asks to be paired with the plugin that shows this code. */
  z.object({ type: z.literal("join"), protocolVersion: z.number().int(), pairingCode: PairingCodeSchema }),
  z.object({ type: z.literal("request"), id: z.string(), method: z.string(), params: z.unknown().optional() }),
  z.object({ type: z.literal("response"), id: z.string(), result: z.unknown().optional(), error: RpcErrorSchema.optional() }),
  z.object({ type: z.literal("progress"), id: z.string(), done: z.number(), total: z.number(), message: z.string().optional() }),
]);
export type ClientMessage = z.infer<typeof ClientMessageSchema>;

export type ServerMessage =
  | { type: "registered"; pairingCode: string }
  | { type: "joined"; pairingCode: string; fileName?: string }
  | { type: "peer_left"; role: "plugin" | "agent" }
  | { type: "request"; id: string; method: string; params?: unknown }
  | { type: "response"; id: string; result?: unknown; error?: RpcError }
  | { type: "progress"; id: string; done: number; total: number; message?: string }
  | { type: "error"; code: string; message: string };

// ---------------------------------------------------------------------------
// Plugin RPC surface (methods executed inside the Figma sandbox)
// ---------------------------------------------------------------------------

export interface NodeSummary {
  id: string;
  name: string;
  type: string;
  width?: number;
  height?: number;
}

export interface TextEntry {
  nodeId: string;
  name: string;
  characters: string;
}

export interface SynthesizeSpec {
  /** Taxonomy name of the new master component, e.g. "Navigation/Bar/Bottom/iOS". */
  name: string;
  role: string;
  width: number;
  height: number;
  surfaceVariableId?: string;
  onSurfaceVariableId?: string;
  fallbackSurface: Rgba;
  fallbackOnSurface: Rgba;
  cornerRadius: number;
  padding: number;
  itemSpacing: number;
  /** Labels for repeated slots (tabs, actions); empty for a single-title bar. */
  slots: string[];
  orientation: "horizontal" | "vertical";
  title?: string;
}

export interface HandoffSpec {
  title: string;
  platformLabel: string;
  ledger: Array<{ token: string; value: string; css: string; tailwind: string; native: string }>;
  notes: Array<{ target: string; text: string }>;
  code: { language: string; text: string };
}

export interface PluginMethods {
  get_document_info: { params: Record<string, never>; result: { fileName: string; pageName: string; selection: NodeSummary[] } };
  get_selection: { params: Record<string, never>; result: NodeSummary[] };
  snapshot: { params: { nodeId: string; depth?: number }; result: NodeSnapshot };
  scan_design_system: { params: Record<string, never>; result: DsIndex };
  create_frame: {
    params: { name: string; width: number; height: number; x?: number; y?: number; parentId?: string; fill?: Rgba };
    result: NodeSummary;
  };
  set_fills: { params: { nodeId: string; color?: Rgba; variableId?: string }; result: NodeSummary };
  set_auto_layout: {
    params: {
      nodeId: string;
      layoutMode: "NONE" | "HORIZONTAL" | "VERTICAL";
      itemSpacing?: number;
      padding?: { top?: number; right?: number; bottom?: number; left?: number };
      primaryAxisAlignItems?: "MIN" | "CENTER" | "MAX" | "SPACE_BETWEEN";
      counterAxisAlignItems?: "MIN" | "CENTER" | "MAX" | "BASELINE";
      layoutWrap?: "NO_WRAP" | "WRAP";
    };
    result: NodeSummary;
  };
  apply_plan: { params: MutationPlan; result: ApplyPlanResult };
  extract_text: { params: { nodeId: string }; result: TextEntry[] };
  apply_text: { params: { updates: Array<{ nodeId: string; characters: string }> }; result: { updated: number; warnings: string[] } };
  synthesize_component: { params: SynthesizeSpec; result: { componentId: string; name: string } };
  render_handoff: { params: { nodeId: string; spec: HandoffSpec }; result: { sectionId: string } };
  remove_nodes: { params: { nodeIds: string[] }; result: { removed: number } };
  export_png: { params: { nodeId: string; maxSize: number }; result: { base64: string; width: number; height: number; name: string } };
}

export type PluginMethod = keyof PluginMethods;
export type PluginParams<M extends PluginMethod> = PluginMethods[M]["params"];
export type PluginResult<M extends PluginMethod> = PluginMethods[M]["result"];
